checks.command:
foreach ($g in "Domain Admins","Enterprise Admins","Schema Admins","Administrators","Account Operators","Backup Operators","Server Operators","Print Operators") {
    "=== $g ==="
    Get-ADGroupMember $g -Recursive -ErrorAction SilentlyContinue | Select Name,objectClass
}

Get-ADOrganizationalUnit -Filter * | ForEach-Object {
    $ou = $_.DistinguishedName
    (Get-GPInheritance -Target $ou).GpoLinks |
        Select-Object @{N='OU';E={$ou}}, DisplayName, Enabled, Enforced
}
